import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [stage, setStage] = useState("singularity"); // singularity -> bang -> warp

  useEffect(() => {
    const bangTimer = setTimeout(() => setStage("bang"), 1000);
    const warpTimer = setTimeout(() => setStage("warp"), 3200);
    const completeTimer = setTimeout(onComplete, 4000);

    return () => { 
      clearTimeout(bangTimer); 
      clearTimeout(warpTimer); 
      clearTimeout(completeTimer); 
    };
  }, [onComplete]);

  return (
    <div className="h-screen w-full bg-black flex items-center justify-center relative overflow-hidden">

      {/* 1. THE SINGULARITY (The "Magic" Dot) */}
      {stage === "singularity" && (
        <motion.div 
          initial={{ scale: 0 }}
          animate={{ scale: [0, 1.5, 1] }}
          transition={{ duration: 0.8, ease: "easeOut" }}
          className="w-4 h-4 bg-[#FF5B03] rounded-full shadow-[0_0_50px_#FF5B03]"
        />
      )}

      {/* 2. THE EXPLOSION UNIT */}
      <div className={stage === "warp" ? "animate-warp" : stage === "bang" ? "animate-bang" : "hidden"}>
        <div className="relative flex flex-col items-center">

          {/* Logo Assembly */}
          <div className="flex items-center justify-center">
            <h1 className="text-[12rem] md:text-[20rem] font-[1000] italic text-[#FDFAD8] tracking-tighter leading-none select-none">
              T
            </h1>

            <div className="relative mx-[-10px] md:mx-[-30px]">
              {/* The "2" with a High-Voltage Glow */}
              <div className="bg-[#FF5B03] w-24 h-24 md:w-44 md:h-44 flex items-center justify-center border-4 border-white shadow-[0_0_100px_rgba(255,91,3,0.5)] rotate-12">
                <span className="text-white text-7xl md:text-[11rem] font-black italic">2</span>
              </div>
              {/* Particle "Dust" around the 2 */}
              <div className="absolute -inset-10 pointer-events-none opacity-40">
                {[...Array(6)].map((_, i) => (
                  <div key={i} className="absolute w-1 h-1 bg-[#CAD23C] rounded-full animate-pulse" 
                       style={{ top: `${Math.random()*100}%`, left: `${Math.random()*100}%`, animationDelay: `${i*0.2}s` }} />
                ))}
              </div>
            </div>

            <h1 className="text-[12rem] md:text-[20rem] font-[1000] italic text-[#FDFAD8] tracking-tighter leading-none select-none">
              T
            </h1>
          </div>

          {/* The "Worker" Strike-Through */}
          <motion.div 
            initial={{ opacity: 0, scaleX: 0 }}
            animate={{ opacity: 1, scaleX: 1 }}
            transition={{ delay: 0.5, duration: 0.5 }}
            className="mt-[-20px] md:mt-[-40px] bg-white px-10 py-2 skew-x-[-20deg]"
          >
            <span className="text-black font-[1000] text-2xl md:text-4xl uppercase tracking-[0.2em] italic">
              Worker
            </span>
          </motion.div>
        </div>
      </div>

      {/* 3. PERIMETER AMBIENCE (Apple-style precision) */}
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
        <div className="w-full h-[1px] bg-gradient-to-r from-transparent via-[#CAD23C]/20 to-transparent" />
        <div className="absolute h-full w-[1px] bg-gradient-to-b from-transparent via-[#CAD23C]/20 to-transparent" />
      </div>

      <div className="absolute bottom-10 text-[#CAD23C] font-black text-[10px] tracking-[1.5em] opacity-30 animate-pulse uppercase">
        Establishing_Neural_Link
      </div>
    </div>
  );
};

export default WorkerSplash;
